using EmployeeTaskManagement.Models;
using EmployeeTaskManagement.Services;
using Microsoft.EntityFrameworkCore;

namespace EmployeeTaskManagement.Data;

public static class DbInitializer
{
    public static async Task SeedAsync(AppDbContext context, IAuthService authService)
    {
        // 1. Ensure tables and columns exist
        var createTablesSql = @"
        CREATE TABLE IF NOT EXISTS ""Users"" (
            ""Id"" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
            ""Name"" character varying(100) NOT NULL,
            ""Email"" character varying(150) NOT NULL,
            ""PasswordHash"" text NOT NULL,
            ""Role"" character varying(50) NOT NULL DEFAULT 'Employee',
            ""CreatedAt"" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP
        );
        CREATE UNIQUE INDEX IF NOT EXISTS ""IX_Users_Email"" ON ""Users"" (""Email"");

        CREATE TABLE IF NOT EXISTS ""Employees"" (
            ""Id"" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
            ""Name"" character varying(100) NOT NULL,
            ""Email"" character varying(150) NOT NULL,
            ""Department"" character varying(100) NOT NULL,
            ""Designation"" character varying(100) NOT NULL,
            ""IsActive"" boolean NOT NULL DEFAULT TRUE,
            ""CreatedAt"" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP
        );
        CREATE UNIQUE INDEX IF NOT EXISTS ""IX_Employees_Email"" ON ""Employees"" (""Email"");

        CREATE TABLE IF NOT EXISTS ""Tasks"" (
            ""Id"" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
            ""Title"" character varying(200) NOT NULL,
            ""Description"" text NOT NULL,
            ""Priority"" character varying(20) NOT NULL DEFAULT 'Medium',
            ""Status"" character varying(20) NOT NULL DEFAULT 'Pending',
            ""DueDate"" timestamp with time zone NOT NULL,
            ""AssignedEmployeeId"" integer NOT NULL,
            ""CreatedById"" integer,
            ""CreatedAt"" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
            ""UpdatedAt"" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
            CONSTRAINT ""FK_Tasks_Employees_AssignedEmployeeId"" FOREIGN KEY (""AssignedEmployeeId"") REFERENCES ""Employees"" (""Id"") ON DELETE RESTRICT,
            CONSTRAINT ""FK_Tasks_Users_CreatedById"" FOREIGN KEY (""CreatedById"") REFERENCES ""Users"" (""Id"") ON DELETE SET NULL
        );

        ALTER TABLE ""Employees"" ALTER COLUMN ""IsActive"" SET DEFAULT TRUE;
        ALTER TABLE ""Tasks"" ADD COLUMN IF NOT EXISTS ""CreatedById"" integer REFERENCES ""Users""(""Id"") ON DELETE SET NULL;
        ALTER TABLE ""Tasks"" ADD COLUMN IF NOT EXISTS ""CreatedAt"" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP;
        ALTER TABLE ""Tasks"" ADD COLUMN IF NOT EXISTS ""UpdatedAt"" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP;
        ALTER TABLE ""Employees"" ADD COLUMN IF NOT EXISTS ""CreatedAt"" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP;
        ALTER TABLE ""Users"" ADD COLUMN IF NOT EXISTS ""CreatedAt"" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP;
        ";

        await context.Database.ExecuteSqlRawAsync(createTablesSql);

        // 2. Seed Admin User
        User? adminUser = await context.Users.FirstOrDefaultAsync(u => u.Email.ToLower() == "admin@example.com");
        if (adminUser == null)
        {
            adminUser = new User
            {
                Name = "Admin User",
                Email = "admin@example.com",
                PasswordHash = authService.HashPassword("Admin@123"),
                Role = "Admin",
                CreatedAt = DateTime.UtcNow
            };
            context.Users.Add(adminUser);
            await context.SaveChangesAsync();
        }
        else
        {
            adminUser.PasswordHash = authService.HashPassword("Admin@123");
            adminUser.Role = "Admin";
            await context.SaveChangesAsync();
        }

        // 3. Seed Sample Employees
        var sampleEmployees = new List<Employee>
        {
            new()
            {
                Name = "John Doe",
                Email = "john.doe@example.com",
                Department = "Engineering",
                Designation = "Senior Software Engineer",
                IsActive = true,
                CreatedAt = DateTime.UtcNow.AddDays(-30)
            },
            new()
            {
                Name = "Sarah Smith",
                Email = "sarah.smith@example.com",
                Department = "UI/UX Design",
                Designation = "Lead Product Designer",
                IsActive = true,
                CreatedAt = DateTime.UtcNow.AddDays(-25)
            },
            new()
            {
                Name = "Mike Johnson",
                Email = "mike.johnson@example.com",
                Department = "Marketing",
                Designation = "Growth Specialist",
                IsActive = true,
                CreatedAt = DateTime.UtcNow.AddDays(-20)
            },
            new()
            {
                Name = "Emily Davis",
                Email = "emily.davis@example.com",
                Department = "Engineering",
                Designation = "QA Automation Engineer",
                IsActive = true,
                CreatedAt = DateTime.UtcNow.AddDays(-15)
            },
            new()
            {
                Name = "Alex Turner",
                Email = "alex.turner@example.com",
                Department = "Human Resources",
                Designation = "HR Operations Specialist",
                IsActive = false,
                CreatedAt = DateTime.UtcNow.AddDays(-40)
            }
        };

        foreach (var emp in sampleEmployees)
        {
            if (!await context.Employees.AnyAsync(e => e.Email.ToLower() == emp.Email.ToLower()))
            {
                context.Employees.Add(emp);
            }
        }
        await context.SaveChangesAsync();

        // 4. Ensure Employee User accounts exist
        string defaultEmployeePasswordHash = authService.HashPassword("Employee@123");
        var allEmployees = await context.Employees.ToListAsync();

        foreach (var emp in allEmployees)
        {
            var user = await context.Users.FirstOrDefaultAsync(u => u.Email.ToLower() == emp.Email.ToLower());
            if (user == null)
            {
                context.Users.Add(new User
                {
                    Name = emp.Name,
                    Email = emp.Email,
                    PasswordHash = defaultEmployeePasswordHash,
                    Role = "Employee",
                    CreatedAt = emp.CreatedAt
                });
            }
            else if (user.Role != "Admin")
            {
                user.PasswordHash = defaultEmployeePasswordHash;
            }
        }
        await context.SaveChangesAsync();

        // 5. Seed Sample Tasks
        var currentTasksCount = await context.Tasks.CountAsync();
        if (currentTasksCount < 5)
        {
            var john = await context.Employees.FirstOrDefaultAsync(e => e.Email == "john.doe@example.com");
            var sarah = await context.Employees.FirstOrDefaultAsync(e => e.Email == "sarah.smith@example.com");
            var mike = await context.Employees.FirstOrDefaultAsync(e => e.Email == "mike.johnson@example.com");
            var emily = await context.Employees.FirstOrDefaultAsync(e => e.Email == "emily.davis@example.com");

            if (john != null && sarah != null && mike != null && emily != null)
            {
                var tasks = new List<TaskItem>
                {
                    new()
                    {
                        Title = "Implement JWT Authentication Endpoints",
                        Description = "Develop and test the authentication service including JWT token generation and validation middleware.",
                        Priority = "High",
                        Status = "Completed",
                        DueDate = DateTime.SpecifyKind(DateTime.UtcNow.AddDays(2), DateTimeKind.Utc),
                        AssignedEmployeeId = john.Id,
                        CreatedById = adminUser.Id,
                        CreatedAt = DateTime.SpecifyKind(DateTime.UtcNow.AddDays(-5), DateTimeKind.Utc),
                        UpdatedAt = DateTime.SpecifyKind(DateTime.UtcNow.AddDays(-1), DateTimeKind.Utc)
                    },
                    new()
                    {
                        Title = "Design Dashboard Wireframes and Mockups",
                        Description = "Create high-fidelity Figma components and user workflows for the employee task analytics dashboard.",
                        Priority = "Medium",
                        Status = "In Progress",
                        DueDate = DateTime.SpecifyKind(DateTime.UtcNow.AddDays(4), DateTimeKind.Utc),
                        AssignedEmployeeId = sarah.Id,
                        CreatedById = adminUser.Id,
                        CreatedAt = DateTime.SpecifyKind(DateTime.UtcNow.AddDays(-4), DateTimeKind.Utc),
                        UpdatedAt = DateTime.SpecifyKind(DateTime.UtcNow.AddDays(-2), DateTimeKind.Utc)
                    },
                    new()
                    {
                        Title = "Launch Q3 Product Update Campaign",
                        Description = "Prepare email newsletters, social media copy, and landing page content for the upcoming release.",
                        Priority = "Low",
                        Status = "Pending",
                        DueDate = DateTime.SpecifyKind(DateTime.UtcNow.AddDays(7), DateTimeKind.Utc),
                        AssignedEmployeeId = mike.Id,
                        CreatedById = adminUser.Id,
                        CreatedAt = DateTime.SpecifyKind(DateTime.UtcNow.AddDays(-3), DateTimeKind.Utc),
                        UpdatedAt = DateTime.SpecifyKind(DateTime.UtcNow.AddDays(-3), DateTimeKind.Utc)
                    },
                    new()
                    {
                        Title = "Setup Automated E2E Test Suite",
                        Description = "Configure Playwright or Cypress test suites for critical user journeys and CI pipeline integration.",
                        Priority = "High",
                        Status = "In Progress",
                        DueDate = DateTime.SpecifyKind(DateTime.UtcNow.AddDays(3), DateTimeKind.Utc),
                        AssignedEmployeeId = emily.Id,
                        CreatedById = adminUser.Id,
                        CreatedAt = DateTime.SpecifyKind(DateTime.UtcNow.AddDays(-3), DateTimeKind.Utc),
                        UpdatedAt = DateTime.SpecifyKind(DateTime.UtcNow.AddDays(-1), DateTimeKind.Utc)
                    },
                    new()
                    {
                        Title = "Optimize Database Queries & Indexes",
                        Description = "Review execution plans and add appropriate indexes to PostgreSQL tables for high performance.",
                        Priority = "Medium",
                        Status = "Pending",
                        DueDate = DateTime.SpecifyKind(DateTime.UtcNow.AddDays(6), DateTimeKind.Utc),
                        AssignedEmployeeId = john.Id,
                        CreatedById = adminUser.Id,
                        CreatedAt = DateTime.SpecifyKind(DateTime.UtcNow.AddDays(-2), DateTimeKind.Utc),
                        UpdatedAt = DateTime.SpecifyKind(DateTime.UtcNow.AddDays(-2), DateTimeKind.Utc)
                    },
                    new()
                    {
                        Title = "Create Responsive Mobile Navigation",
                        Description = "Refactor the main application layout to ensure smooth responsive experience on tablets and smartphones.",
                        Priority = "Low",
                        Status = "Completed",
                        DueDate = DateTime.SpecifyKind(DateTime.UtcNow.AddDays(-1), DateTimeKind.Utc),
                        AssignedEmployeeId = sarah.Id,
                        CreatedById = adminUser.Id,
                        CreatedAt = DateTime.SpecifyKind(DateTime.UtcNow.AddDays(-6), DateTimeKind.Utc),
                        UpdatedAt = DateTime.SpecifyKind(DateTime.UtcNow.AddDays(-1), DateTimeKind.Utc)
                    },
                    new()
                    {
                        Title = "Write User Documentation and API Guide",
                        Description = "Document REST API endpoints, request schemas, and swagger usage for developer onboarding.",
                        Priority = "Medium",
                        Status = "Pending",
                        DueDate = DateTime.SpecifyKind(DateTime.UtcNow.AddDays(8), DateTimeKind.Utc),
                        AssignedEmployeeId = emily.Id,
                        CreatedById = adminUser.Id,
                        CreatedAt = DateTime.SpecifyKind(DateTime.UtcNow.AddDays(-1), DateTimeKind.Utc),
                        UpdatedAt = DateTime.SpecifyKind(DateTime.UtcNow.AddDays(-1), DateTimeKind.Utc)
                    }
                };

                context.Tasks.AddRange(tasks);
                await context.SaveChangesAsync();
            }
        }
    }
}
